<?php defined('BASEPATH') or exit('No direct script access allowed');
$taskFormHidden=function(string $action,int $revision,?int $task=null)use($hidden,$esc,$operation_detail){$hidden($action); ?><input type="hidden" name="project_id" value="<?= (int)$operation_detail['id']; ?>"><input type="hidden" name="revision" value="<?= $revision; ?>"><input type="hidden" name="request_key" value="<?= $esc(bin2hex(random_bytes(32))); ?>"><?php if($task!==null){ ?><input type="hidden" name="task_id" value="<?= $task; ?>"><?php }};
$taskFields=function(string $prefix,array $values)use($esc){ ?><label for="<?= $esc($prefix); ?>-name">Nome da tarefa</label><input id="<?= $esc($prefix); ?>-name" name="task[name]" maxlength="191" required value="<?= $esc($values['name']??''); ?>"><label for="<?= $esc($prefix); ?>-description">Descrição em texto</label><textarea id="<?= $esc($prefix); ?>-description" name="task[description]" maxlength="4000" rows="5"><?= $esc($values['description']??''); ?></textarea><label for="<?= $esc($prefix); ?>-due">Prazo dentro da vigência do projeto</label><input id="<?= $esc($prefix); ?>-due" name="task[due_date]" type="date" required value="<?= $esc($values['due_date']??''); ?>"><?php };
?>
<?php if(is_array($author_tasks??null)){ ?><section id="portal-author-tasks"><h3>Suas tarefas e resultados privados</h3><p>Retome suas tarefas por este projeto. Esta lista pertence ao seu contato; outros contatos não recebem seus resultados privados.</p><?php foreach($author_tasks['items'] as $ownTask){ ?><p><a href="<?= $esc($url.'?operation_kind=projects&resource_id='.(int)$operation_detail['id'].'&task_receipt='.$ownTask['request_key']); ?>"><?= $esc($ownTask['name']); ?></a></p><?php }if(!$author_tasks['items']){ ?><p>Nenhuma tarefa própria disponível.</p><?php }if($author_tasks['next']!==null){ ?><a href="<?= $esc($url.'?operation_kind=projects&resource_id='.(int)$operation_detail['id'].'&author_tasks_after='.(int)$author_tasks['next']); ?>">Mais tarefas próprias</a><?php } ?></section><?php } ?>
<?php if(is_array($task_receipt??null)){ ?><section id="portal-task-receipt"><h3>Seu resultado privado</h3><p>Envio registrado para você e a equipe. Este recibo não publica sua tarefa, comentário ou arquivo para outros contatos. Você pode continuar pelas ações permitidas abaixo. A equipe decide separadamente a publicação pública; alterações de tarefa podem retirar a versão pública anterior até nova publicação.</p><p><?= $esc($task_receipt['created_at'].' · '.$task_receipt['receipt']['author_name']); ?></p><p><?= $task_receipt['public_current']?'A versão atual da tarefa foi publicada. Comentários e anexos dependem de publicação individual.':'A versão atual permanece privada para você e a equipe; a lista pública pode não exibi-la.'; ?></p><div id="portal-task-receipt-evidence" style="white-space:pre-wrap"><?php foreach($task_receipt['receipt']['data'] as $f=>$v)if(in_array($f,['name','description','due_date','body','filename','mime'],true))echo $esc($v)."\n"; ?></div>
<?php if($task_receipt['receipt']['operation']==='upload'&&$task_receipt['file_available']){ ?><?= form_open($url,['id'=>'portal-task-receipt-download']);$hidden('project_task_receipt_file'); ?><input type="hidden" name="project_id" value="<?= (int)$operation_detail['id']; ?>"><input type="hidden" name="receipt_key" value="<?= $esc($task_receipt['request_key']); ?>"><button type="submit">Baixar seu arquivo privado</button><?= form_close(); ?><?= form_open($url,['id'=>'portal-task-receipt-hide']);$taskFormHidden('project_task_hide',(int)$task_receipt['task_revision'],(int)$task_receipt['task_id']); ?><input type="hidden" name="file_key" value="<?= $esc($task_receipt['receipt']['result_key']); ?>"><button type="submit">Ocultar seu arquivo e preservar histórico</button><?= form_close(); ?><?php } ?><a href="<?= $esc($url.'?operation_kind=projects&resource_id='.(int)$operation_detail['id'].'&task_receipt='.$task_receipt['request_key']); ?>">Reabrir este resultado privado</a></section><?php } ?>
<?php $writeValues=$task_receipt['own_task']??$project_task??null;$writeTask=is_array($writeValues)?(int)$writeValues['id']:null;$wc=$task_write_controls??null;if(is_array($wc)&&$writeTask!==null){ ?><section id="portal-task-actions"><h3>Ações permitidas para esta tarefa</h3><p>Seus comentários e arquivos ficam destinados a você e à equipe até publicação individual para outros contatos. Conclusão, responsáveis e checklist são controlados pela equipe.</p><?php if($wc['edit_tasks']){ ?><?= form_open($url,['id'=>'portal-task-edit']);$taskFormHidden('project_task_edit',(int)$wc['revision'],$writeTask);$taskFields('portal-task-edit',$writeValues); ?><button type="submit">Salvar sua tarefa</button><?= form_close(); ?><?php }if($wc['comment_on_tasks']){ ?><?= form_open($url,['id'=>'portal-task-comment']);$taskFormHidden('project_task_comment',(int)$wc['revision'],$writeTask); ?><label for="portal-task-comment-body">Seu comentário em texto</label><textarea id="portal-task-comment-body" name="comment_body" maxlength="4000" rows="5" required></textarea><button type="submit">Registrar comentário privado</button><?= form_close(); ?><?php }if($wc['upload_on_tasks']){ ?><?= form_open_multipart($url,['id'=>'portal-task-upload']);$taskFormHidden('project_task_upload',(int)$wc['revision'],$writeTask); ?><label for="portal-task-upload-file">Anexo para você e a equipe</label><input id="portal-task-upload-file" type="file" name="operation_file" accept=".pdf,.png,.jpg,.jpeg" required><p>PDF até2MiB ou PNG/JPEG até512KiB normalizados; até20 arquivos/20MiB incluindo ocultos. Publicação para outros contatos é individual e explícita.</p><button type="submit">Anexar à tarefa para você e a equipe</button><?= form_close(); ?><?php } ?></section><?php } ?>
<?php if(($project_task_create_controls['create_tasks']??false)){ ?><section id="portal-project-create-task"><h3>Criar sua tarefa no projeto</h3><p>Nova tarefa sem responsável atribuído, disponível a você e à equipe. Sua autoria será preservada. Outros contatos somente a verão depois de publicação explícita da equipe. Você poderá editar sua tarefa enquanto não faturada e autorizada; não há faturamento de tarefas isoladas disponível neste fluxo.</p><?= form_open($url,['id'=>'portal-task-create']);$taskFormHidden('project_task_create',(int)$project_task_create_controls['project_revision']);$taskFields('portal-task-create',[]); ?><button type="submit">Criar sua tarefa</button><?= form_close(); ?></section><?php } ?>
